SELECT COUNT(*) AS order_count, MIN(placed_at) AS earliest, MAX(placed_at) AS latest
FROM orders
WHERE placed_at >= '2026-07-01' AND placed_at < '2026-10-01';

SELECT COUNT(*) AS order_count
FROM orders
WHERE placed_at >= '2026-07-01' AND placed_at < '2026-10-01';

SELECT COUNT(DISTINCT o.order_id) AS order_count
FROM orders o
WHERE o.placed_at >= '2026-07-01' AND o.placed_at < '2026-10-01';

SELECT
  COUNT(*) FILTER (
    WHERE EXTRACT(DOW FROM created_at) IN (0,6)
  ) AS weekend_total,
  COUNT(*) FILTER (
    WHERE EXTRACT(DOW FROM created_at) IN (0,6)
    AND EXTRACT(HOUR FROM created_at) BETWEEN 12 AND 17
  ) AS weekend_afternoon
FROM service_requests;

SELECT c.customer_id, c.email
FROM customers c
LIMIT 5;
